// File to store same functions from gameLoop and gameState

import { Talent, GameState, Effect } from "../types";
import { Condition } from "../types";
import { performanceMonitor } from "../utils/performanceMonitor";

// Кэш для расчетов множителей
interface MultiplierCacheEntry {
  timestamp: number;
  value: number;
  key: string;
}

const multiplierCache = new Map<string, MultiplierCacheEntry>();
const CACHE_TTL = 100; // Время жизни кэша в миллисекундах

const getCacheKey = (baseCPS: number, level: number, upgradeId: string, sphere: string, multipliers: Record<string, number>, upgradeMultipliers: Record<string, number>, projectMultiplier: number): string => {
  return `${baseCPS}-${level}-${upgradeId}-${sphere}-${JSON.stringify(multipliers)}-${JSON.stringify(upgradeMultipliers)}-${projectMultiplier}`;
};

const getCachedValue = (key: string): number | null => {
  const entry = multiplierCache.get(key);
  if (entry && Date.now() - entry.timestamp < CACHE_TTL) {
    performanceMonitor.recordCacheHit();
    return entry.value;
  }
  performanceMonitor.recordCacheMiss();
  return null;
};

const setCachedValue = (key: string, value: number): void => {
  multiplierCache.set(key, {
    timestamp: Date.now(),
    value,
    key
  });
  
  // Очистка старых записей
  if (multiplierCache.size > 1000) {
    const now = Date.now();
    Array.from(multiplierCache.entries()).forEach(([k, entry]) => {
      if (now - entry.timestamp > CACHE_TTL) {
        multiplierCache.delete(k);
      }
    });
  }
};

export const applyTalentEffect = (effects: Effect[], state: GameState) => {
    // Apply all effects of the talent
    effects.forEach(effect => {
      effect(state);
    });
}

// Функция для оценки условий видимости в виде строк
export const evaluateVisibility = (visibilityCondition: boolean | Condition, state: GameState): boolean => {
  if (typeof visibilityCondition === 'boolean') {
    return visibilityCondition;
  }
  return visibilityCondition(state);
}

/**
 * Преобразует эффекты (функции) в читаемые для игрока строки
 * @param effects Массив эффектов (функций)
 * @returns Массив строк с описанием эффектов
 */
export const getEffectsDescription = (effects: Effect[]): string[] => {
  const effectsDescription: string[] = [];
  
  effects.forEach(effect => {
    // Получаем строковое представление функции
    const functionString = effect.toString();
    
    // Поиск увеличения множителей в разных сферах
    if (functionString.includes('multipliers[')) {
      if (functionString.includes('ECONOMY')) {
        // Извлекаем процент
        const match = functionString.match(/\+=\s*([\d.]+)/);
        if (match) {
          const percent = parseFloat(match[1]) * 100;
          effectsDescription.push(`Увеличивает эффективность экономики на <span class="positive">+${percent}%</span>`);
        }
      }
      if (functionString.includes('SCIENCE')) {
        const match = functionString.match(/\+=\s*([\d.]+)/);
        if (match) {
          const percent = parseFloat(match[1]) * 100;
          effectsDescription.push(`Увеличивает эффективность науки на <span class="positive">+${percent}%</span>`);
        }
      }
      if (functionString.includes('FAITH')) {
        const match = functionString.match(/\+=\s*([\d.]+)/);
        if (match) {
          const percent = parseFloat(match[1]) * 100;
          effectsDescription.push(`Увеличивает эффективность веры на <span class="positive">+${percent}%</span>`);
        }
      }
    }
    
    // Скорость завоевания
    if (functionString.includes('conquestSpeed')) {
      const match = functionString.match(/\+=\s*([\d.]+)/);
      if (match) {
        const percent = parseFloat(match[1]) * 100;
        effectsDescription.push(`Увеличивает скорость завоевания на <span class="positive">+${percent}%</span>`);
      }
    }
    
    // Скорость проектов
    if (functionString.includes('projectSpeed')) {
      const match = functionString.match(/\+=\s*([\d.]+)/);
      if (match) {
        const percent = parseFloat(match[1]) * 100;
        effectsDescription.push(`Увеличивает скорость проектов на <span class="positive">+${percent}%</span>`);
      }
    }
    
    // Сила ручного клика
    if (functionString.includes('manualClickPower')) {
      const match = functionString.match(/\+=\s*([\d.]+)/);
      if (match) {
        const value = parseFloat(match[1]);
        effectsDescription.push(`Увеличивает силу клика на <span class="positive">+${value}</span>`);
      }
    }
    
    // Проекты
    if (functionString.includes('activeProjects.push')) {
      const match = functionString.match(/id:\s*'([^']+)'/);
      if (match) {
        const projectId = match[1];
        effectsDescription.push(`Запускает проект "<span class="project">${projectId}</span>"`);
      }
    }
    
    // Завоевание стран
    if (functionString.includes('conqueredCountries.push')) {
      effectsDescription.push(`Завоевывает новую случайную страну`);
    }
    
    // Снятие ресурсов
    if (functionString.includes('resources -=')) {
      const match = functionString.match(/resources\s*-=\s*([\d.]+)/);
      if (match) {
        const cost = parseFloat(match[1]);
        effectsDescription.push(`Стоимость: <span class="cost">${cost}</span> общих ресурсов`);
      }
    }
    
    // Добавление ресурсов
    if (functionString.includes('resources +=')) {
      const match = functionString.match(/resources\s*\+=\s*([\d.]+)/);
      if (match) {
        const gain = parseFloat(match[1]);
        effectsDescription.push(`Получено <span class="positive">+${gain}</span> общих ресурсов`);
      }
    }
  });
  
  // Если не нашли эффектов, добавляем общий эффект
  if (effectsDescription.length === 0) {
    effectsDescription.push('Эффект активирован');
  }
  
  return effectsDescription;
}

const DEFAULT_CONFIG = {
  baseCost: 10,
  growthRate: Math.pow(100, 1/9), // ≈1.6681
  transitionLevel: 100,
  linearIncrement: 500,
};
export const calculateUpgradeCost = (level: number, config = DEFAULT_CONFIG) => {
  const { baseCost, growthRate, transitionLevel, linearIncrement } = config;

  if (level === 0) {
    return baseCost;
  }


  if (level <= transitionLevel) {
    // Экспоненциальный рост: baseCost * growthRate^(level-1)
    return baseCost * Math.pow( growthRate, Math.max(level, 1) )
    
  }

  // Расчет стоимости на уровне перехода
  const costAtTransition = baseCost * Math.pow( growthRate, transitionLevel )

  // Линейный рост после переходного уровня
  return costAtTransition + linearIncrement
}

// Функция для расчета эффективного CPS апгрейда с учетом всех множителей
export const calculateEffectiveCPS = (
  baseCPS: number,
  upgradeId: string,
  sphere: string,
  state: { multipliers: Record<string, number>; upgradeMultipliers: Record<string, number> }
): number => {
  const sphereMultiplier = state.multipliers[sphere] || 1.0;
  const upgradeMultiplier = state.upgradeMultipliers[upgradeId] || 1.0;
  return baseCPS * (sphereMultiplier + upgradeMultiplier);
};

// Функция для расчета общего CPS от всех уровней апгрейда
export const calculateTotalUpgradeCPS = (
  baseCPS: number,
  level: number,
  upgradeId: string,
  sphere: string,
  state: { multipliers: Record<string, number>; upgradeMultipliers: Record<string, number>; projectMultiplier: number }
): number => {
  performanceMonitor.startTimer('multiplierCalculation');
  
  const projectMultiplier = state.projectMultiplier || 1.0;
  
  // Проверяем кэш
  const cacheKey = getCacheKey(baseCPS, level, upgradeId, sphere, state.multipliers, state.upgradeMultipliers, projectMultiplier);
  const cachedValue = getCachedValue(cacheKey);
  if (cachedValue !== null) {
    performanceMonitor.endTimer('multiplierCalculation');
    return cachedValue;
  }
  
  // Вычисляем значение
  const effectiveCPS = calculateEffectiveCPS(baseCPS, upgradeId, sphere, state);
  const result = effectiveCPS * level * projectMultiplier;
  
  // Сохраняем в кэш
  setCachedValue(cacheKey, result);
  
  performanceMonitor.endTimer('multiplierCalculation');
  return result;
};