// Функция для определения, какой проект запускает талант
export const getProjectFromTalent = (talent: Talent) => {
  // Проверяем эффекты таланта на наличие добавления проектов
  for (const effect of talent.effects) {
    const effectString = effect.toString();
    
    // Ищем паттерны добавления проектов в activeProjects
    const projectMatch = effectString.match(/activeProjects\.push\(\{\s*id:\s*['"`]([^'"`]+)['"`]/);
    if (projectMatch) {
      const projectId = projectMatch[1];
      const project = Projects[projectId];
      if (project) {
        return {
          key: projectId,
          name: project.name,
          description: project.description,
          image: project.icon
        };
      }
    }
  }
  return null;
};
