interface PerformanceMetrics {
  multiplierCalculations: {
    count: number;
    totalTime: number;
    averageTime: number;
    maxTime: number;
  };
  cacheHits: number;
  cacheMisses: number;
  memoryUsage: {
    used: number;
    total: number;
    percentage: number;
  };
  reduxDispatches: number;
}

class PerformanceMonitor {
  private metrics: PerformanceMetrics = {
    multiplierCalculations: {
      count: 0,
      totalTime: 0,
      averageTime: 0,
      maxTime: 0
    },
    cacheHits: 0,
    cacheMisses: 0,
    memoryUsage: {
      used: 0,
      total: 0,
      percentage: 0
    },
    reduxDispatches: 0
  };

  private startTimes = new Map<string, number>();

  startTimer(operation: string): void {
    this.startTimes.set(operation, performance.now());
  }

  endTimer(operation: string): number {
    const startTime = this.startTimes.get(operation);
    if (!startTime) return 0;
    
    const duration = performance.now() - startTime;
    this.startTimes.delete(operation);
    
    if (operation === 'multiplierCalculation') {
      this.metrics.multiplierCalculations.count++;
      this.metrics.multiplierCalculations.totalTime += duration;
      this.metrics.multiplierCalculations.averageTime = 
        this.metrics.multiplierCalculations.totalTime / this.metrics.multiplierCalculations.count;
      this.metrics.multiplierCalculations.maxTime = 
        Math.max(this.metrics.multiplierCalculations.maxTime, duration);
    }
    
    return duration;
  }

  recordCacheHit(): void {
    this.metrics.cacheHits++;
  }

  recordCacheMiss(): void {
    this.metrics.cacheMisses++;
  }

  recordReduxDispatch(): void {
    this.metrics.reduxDispatches++;
  }

  updateMemoryUsage(): void {
    if ('memory' in performance) {
      const memory = (performance as any).memory;
      this.metrics.memoryUsage = {
        used: memory.usedJSHeapSize,
        total: memory.totalJSHeapSize,
        percentage: (memory.usedJSHeapSize / memory.totalJSHeapSize) * 100
      };
    }
  }

  getMetrics(): PerformanceMetrics {
    return { ...this.metrics };
  }

  getCacheHitRate(): number {
    const total = this.metrics.cacheHits + this.metrics.cacheMisses;
    return total > 0 ? this.metrics.cacheHits / total : 0;
  }

  reset(): void {
    this.metrics = {
      multiplierCalculations: {
        count: 0,
        totalTime: 0,
        averageTime: 0,
        maxTime: 0
      },
      cacheHits: 0,
      cacheMisses: 0,
      memoryUsage: {
        used: 0,
        total: 0,
        percentage: 0
      },
      reduxDispatches: 0
    };
  }

  logMetrics(): void {
    this.updateMemoryUsage();
    const hitRate = this.getCacheHitRate();
    console.log('Performance Metrics:', {
      ...this.metrics,
      cacheHitRate: `${(hitRate * 100).toFixed(2)}%`,
      memoryUsage: {
        ...this.metrics.memoryUsage,
        used: `${(this.metrics.memoryUsage.used / 1024 / 1024).toFixed(2)} MB`,
        total: `${(this.metrics.memoryUsage.total / 1024 / 1024).toFixed(2)} MB`,
        percentage: `${this.metrics.memoryUsage.percentage.toFixed(2)}%`
      }
    });
  }
}

export const performanceMonitor = new PerformanceMonitor();