import { CONQUEST_CD } from "../constants";
import { GameState } from "../../types";
import { COUNTRIES } from "../../Countries";

// Функция для расчета динамического времени между захватами
const calculateConquestCooldown = (total: number, conquestSpeed: number): number => {
  // Базовое время - 40 секунд
  const baseTime = CONQUEST_CD;

  // При total = 0: полное базовое время (40 сек)
  // При total = 100_000_000_000 (100б): минимальное время (1-5 сек)

  // Используем логарифмическое уменьшение времени
  const speedFactor = Math.log10(Math.max(1, total / 1000)) / 10; // от 0 до ~0.8
  const dynamicMultiplier = Math.max(0.025, 1 - speedFactor); // от 1 до 0.025 (2.5%)

  // Применяем множитель скорости завоеваний и динамический множитель
  const finalCooldown = (baseTime * dynamicMultiplier) / conquestSpeed;

  // Ограничиваем минимальное время 1 секундой, максимальное - базовым временем
  return Math.max(1000, Math.min(baseTime / conquestSpeed, finalCooldown));
};

// Объединенная функция для обработки всех типов завоеваний
export const checkConquests = (state: GameState, deltaTime: number) => {
  const updates = {
    lastConquest: state.lastConquest,
    conqueredCountries: [...state.conqueredCountries],
    empirePerimeter: [...state.empirePerimeter],
    activeConquests: [...state.activeConquests],
    resources: state.resources,
    flags: [...state.flags],
    autoClickPower: state.autoClickPower,
    newlyConqueredCountries: [] as Array<{ countryName: string, autoPower: number }> // Новое поле для отслеживания захваченных стран
  };

  const now = Date.now();

  // 1. Проверяем автоматическое завоевание соседних стран (с задержкой 3 секунды)
  const countryToConquer = state.empirePerimeter[Math.round(Math.random() * state.empirePerimeter.length)];
  const possibleToConquer = Math.random() > (COUNTRIES[countryToConquer]?.conquestChanse || 0);

  // Рассчитываем динамическое время между захватами
  const dynamicConquestCooldown = calculateConquestCooldown(state.total, state.conquestSpeed);

  // no conquest till we have 10 clicks
  if (countryToConquer && possibleToConquer && state.total > 10 &&
    !updates.conqueredCountries.includes(countryToConquer) &&
    (now - state.lastConquest.lastTriggered) >= dynamicConquestCooldown) {

    // Проверяем, есть ли уже активный захват для этой страны
    const existingConquest = updates.activeConquests.find(c => c.countryId === countryToConquer);
    
    if (!existingConquest) {
      // Создаем новый активный захват с задержкой 10 секунд
      updates.activeConquests.push({
        id: `auto-conquest-${countryToConquer}-${now}`,
        countryId: countryToConquer,
        flagId: '', // Для автоматического захвата флаг не используется
        startTime: now,
        duration: 10000 // 10 секунд
      });
      
      // Обновляем время последнего захвата, чтобы не создавать дубликаты
      updates.lastConquest = {
        lastTriggered: now,
        country: countryToConquer
      };
    }
  }

  // 2. Проверяем все активные захваты (через флаги и автоматические)
  updates.activeConquests = updates.activeConquests.filter((conquest) => {
    const elapsed = now - conquest.startTime;

    if (elapsed >= conquest.duration) {
      // Захват завершен
      const countryData = COUNTRIES[conquest.countryId];

      // Захватываем страну (проверяем что еще не захвачена)
      if (!updates.conqueredCountries.includes(conquest.countryId)) {
        updates.conqueredCountries.push(conquest.countryId);

        // Добавляем силу автоматического клика
        updates.autoClickPower += countryData?.autoPower ?? 0;

        // Расширяем периметр империи
        if (countryData) {
          const conqueredCountryPerimeter = countryData.neighbours.filter(c =>
            !updates.empirePerimeter.includes(c)
          );
          updates.empirePerimeter = [
            ...updates.empirePerimeter.filter(c => c !== conquest.countryId), // filter out that country for caution
            ...conqueredCountryPerimeter // perimeter around new country, but filter overlaps
          ];
        }

        // Выполняем бонус за захват, если есть
        if (countryData?.conquestBonus) {
          // Создаем временное состояние для применения бонуса
          const tempState = {
            ...state,
            conqueredCountries: updates.conqueredCountries,
            resources: updates.resources
          };
          countryData.conquestBonus(tempState);
          // Применяем изменения обратно к updates
          updates.resources = tempState.resources;
        }

        // Добавляем информацию о захваченной стране для отображения эффекта
        updates.newlyConqueredCountries.push({
          countryName: conquest.countryId,
          autoPower: countryData?.autoPower || 0
        });
      }

      // Удаляем использованный флаг (только если это захват через флаг)
      if (conquest.flagId) {
        updates.flags = updates.flags.filter((flag) => flag.id !== conquest.flagId);
      }

      return false; // Удаляем завершенный захват
    }

    return true; // Оставляем активный захват
  });

  return updates;
} 